import java.util.*;

public class Main {
    static int[] goal = {1, 2, 3, 4, 5, 6, 7, 8, 0};

    // Neighbors for each position (up, down, left, right)
    static int[][] neighbors = {
        {1, 3},       // 0
        {0, 2, 4},    // 1
        {1, 5},       // 2
        {0, 4, 6},    // 3
        {1, 3, 5, 7}, // 4
        {2, 4, 8},    // 5
        {3, 7},       // 6
        {6, 8, 4},    // 7
        {7, 5}        // 8
    };

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] initial = new int[9];
        for (int i = 0; i < 9; i++) {
            initial[i] = sc.nextInt();
        }

        System.out.println(bfs(initial));
    }

    static int bfs(int[] initial) {
        String goalStr = Arrays.toString(goal);
        String initStr = Arrays.toString(initial);

        if (initStr.equals(goalStr)) return 0;

        Map<String, Integer> visited = new HashMap<>();
        Queue<int[]> queue = new LinkedList<>();

        queue.offer(initial);
        visited.put(initStr, 0);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            String curStr = Arrays.toString(current);
            int steps = visited.get(curStr);

            // Find position of 0
            int zeroPos = -1;
            for (int i = 0; i < 9; i++) {
                if (current[i] == 0) {
                    zeroPos = i;
                    break;
                }
            }

            for (int neighbor : neighbors[zeroPos]) {
                int[] next = current.clone();
                next[zeroPos] = next[neighbor];
                next[neighbor] = 0;

                String nextStr = Arrays.toString(next);
                if (!visited.containsKey(nextStr)) {
                    if (nextStr.equals(goalStr)) return steps + 1;
                    visited.put(nextStr, steps + 1);
                    queue.offer(next);
                }
            }
        }

        return -1; // No solution
    }
}

import java.util.*;

public class EightPuzzleSolver {
    static final String GOAL = "123456780";
    static final int[] MOVES = {-1, 1, -3, 3}; // left, right, up, down

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        StringBuilder start = new StringBuilder();
        for (int i = 0; i < 9; i++) {
            start.append(sc.next());
        }
        sc.close();

        String startState = start.toString();
        System.out.println(bfs(startState));
    }

    static int bfs(String start) {
        if (start.equals(GOAL)) return 0;

        Queue<String> queue = new LinkedList<>();
        Map<String, Integer> dist = new HashMap<>();
        queue.add(start);
        dist.put(start, 0);

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            int d = dist.get(cur);
            int zeroIdx = cur.indexOf('0');

            for (int move : MOVES) {
                int newIdx = zeroIdx + move;
                if (newIdx < 0 || newIdx >= 9) continue;
                // Prevent invalid moves across rows
                if ((zeroIdx % 3 == 0 && move == -1) || (zeroIdx % 3 == 2 && move == 1)) continue;

                char[] arr = cur.toCharArray();
                arr[zeroIdx] = arr[newIdx];
                arr[newIdx] = '0';
                String next = new String(arr);

                if (!dist.containsKey(next)) {
                    if (next.equals(GOAL)) return d + 1;
                    dist.put(next, d + 1);
                    queue.add(next);
                }
            }
        }
        return -1; // unsolvable
    }
}

