// Encode state as integer for hashing
// State is 3x3 grid, each cell 0-8, encode as base-9 number

#define MAX_STATES 362880

typedef struct {
    int board[9];
    int steps;
} State;

// Visited array using hash
int visited[MAX_STATES];
int dist[MAX_STATES];

// Factorial for encoding
int fact[9] = {1, 1, 2, 6, 24, 120, 720, 5040, 40320};

// Encode board to unique index using Lehmer code
int encode(int *board) {
    int code = 0;
    for (int i = 0; i < 9; i++) {
        int cnt = 0;
        for (int j = i + 1; j < 9; j++) {
            if (board[j] < board[i]) cnt++;
        }
        code += cnt * fact[8 - i];
    }
    return code;
}

// BFS queue
State queue[MAX_STATES];
int qhead, qtail;

// Moves: up, down, left, right (movement of empty space)
int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};

// Target state
int target[9] = {1, 2, 3, 4, 5, 6, 7, 8, 0};

int bfs(int *start) {
    memset(visited, 0, sizeof(visited));

    int target_code = encode(target);
    int start_code = encode(start);

    if (start_code == target_code) return 0;

    qhead = qtail = 0;

    memcpy(queue[qtail].board, start, 9 * sizeof(int));
    queue[qtail].steps = 0;
    qtail++;

    visited[start_code] = 1;

    while (qhead < qtail) {
        State cur = queue[qhead++];

        // Find empty space
        int empty = -1;
        for (int i = 0; i < 9; i++) {
            if (cur.board[i] == 0) {
                empty = i;
                break;
            }
        }

        int er = empty / 3;
        int ec = empty % 3;

        for (int d = 0; d < 4; d++) {
            int nr = er + dr[d];
            int nc = ec + dc[d];

            if (nr < 0 || nr >= 3 || nc < 0 || nc >= 3) continue;

            int npos = nr * 3 + nc;

            State next;
            memcpy(next.board, cur.board, 9 * sizeof(int));
            next.steps = cur.steps + 1;

            // Swap empty and neighbor
            next.board[empty] = next.board[npos];
            next.board[npos] = 0;

            int code = encode(next.board);

            if (code == target_code) return next.steps;

            if (!visited[code]) {
                visited[code] = 1;
                queue[qtail++] = next;
            }
        }
    }

    return -1; // No solution
}

