#define MAXS 362880

typedef struct {
    unsigned char a[9];
    int zero;
    int dist;
} Node;

static int fact[10];
static unsigned char visited[MAXS];

int cantor_rank(const unsigned char s[9]) {
    int rank = 0;
    for (int i = 0; i < 9; i++) {
        int cnt = 0;
        for (int j = i + 1; j < 9; j++) {
            if (s[j] < s[i]) cnt++;
        }
        rank += cnt * fact[8 - i];
    }
    return rank;
}

int is_solvable(const unsigned char s[9]) {
    int inv = 0;
    for (int i = 0; i < 9; i++) {
        if (s[i] == 0) continue;
        for (int j = i + 1; j < 9; j++) {
            if (s[j] != 0 && s[i] > s[j]) inv++;
        }
    }
    return (inv % 2 == 0);
}

int main(void) {
    fact[0] = 1;
    for (int i = 1; i <= 9; i++) fact[i] = fact[i - 1] * i;

    unsigned char start[9];
    int zero = -1;
    for (int i = 0; i < 9; i++) {
        int x;
        if (scanf("%d", &x) != 1) return 0;
        start[i] = (unsigned char)x;
        if (x == 0) zero = i;
    }

    unsigned char target[9] = {1, 2, 3, 4, 5, 6, 7, 8, 0};

    if (!is_solvable(start)) {
        printf("-1\n");
        return 0;
    }

    if (memcmp(start, target, 9) == 0) {
        printf("0\n");
        return 0;
    }

    Node *queue = (Node *)malloc(sizeof(Node) * MAXS);
    int head = 0, tail = 0;

    Node first;
    memcpy(first.a, start, 9);
    first.zero = zero;
    first.dist = 0;

    int r = cantor_rank(start);
    visited[r] = 1;
    queue[tail++] = first;

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    while (head < tail) {
        Node cur = queue[head++];
        int zr = cur.zero / 3;
        int zc = cur.zero % 3;

        for (int k = 0; k < 4; k++) {
            int nr = zr + dr[k];
            int nc = zc + dc[k];
            if (nr < 0 || nr >= 3 || nc < 0 || nc >= 3) continue;

            int nz = nr * 3 + nc;
            Node nxt = cur;
            nxt.a[cur.zero] = nxt.a[nz];
            nxt.a[nz] = 0;
            nxt.zero = nz;
            nxt.dist = cur.dist + 1;

            int rk = cantor_rank(nxt.a);
            if (visited[rk]) continue;
            visited[rk] = 1;

            if (memcmp(nxt.a, target, 9) == 0) {
                printf("%d\n", nxt.dist);
                free(queue);
                return 0;
            }

            queue[tail++] = nxt;
        }
    }

    printf("-1\n");
    free(queue);
    return 0;
}

