import sys
from collections import deque

def serialize(board):
    return ''.join(map(str, board))

def is_solvable(board):
    arr = [x for x in board if x != 0]
    inv = 0
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] > arr[j]:
                inv += 1
    return inv % 2 == 0

def main():
    data = list(map(int, sys.stdin.read().split()))
    start = data[:9]
    target = "123456780"

    if serialize(start) == target:
        print(0)
        return

    if not is_solvable(start):
        print(-1)
        return

    neighbors = {
        0: [1, 3],
        1: [0, 2, 4],
        2: [1, 5],
        3: [0, 4, 6],
        4: [1, 3, 5, 7],
        5: [2, 4, 8],
        6: [3, 7],
        7: [4, 6, 8],
        8: [5, 7],
    }

    start_s = serialize(start)
    q = deque([(start_s, start_s.index('0'), 0)])
    visited = {start_s}

    while q:
        state, z, dist = q.popleft()
        for nz in neighbors[z]:
            lst = list(state)
            lst[z], lst[nz] = lst[nz], lst[z]
            nxt = ''.join(lst)
            if nxt not in visited:
                if nxt == target:
                    print(dist + 1)
                    return
                visited.add(nxt)
                q.append((nxt, nz, dist + 1))

    print(-1)

if __name__ == "__main__":
